-- Ireland deep-dive page translations: page fields, stats, cards (incl.
-- badge_label/badge_type), steps, portal. No penalty rows (none published).

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol + reporte en tiempo real (híbrido)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las especificaciones técnicas exactas de Irlanda, los campos de datos a reportar y el régimen de sanciones aún se están finalizando — confirme los requisitos actuales directamente con Revenue antes de construir una integración.', 'El programa de Modernización del IVA de Irlanda ha pasado de la consulta a un alcance confirmado más rápido que la mayoría — los criterios de contribuyentes de la Fase 1 quedaron fijados más de dos años antes de su entrada en vigor.', 'La dirección de Irlanda está clara aunque los últimos detalles técnicos no estén cerrados — esto supone un paso claro por delante de la cuestión de formato aún abierta en el Reino Unido.', 'Irlanda se sitúa entre el modelo puramente descentralizado del Reino Unido y el modelo de compensación completo de Francia o Polonia — las facturas no necesitan aprobación previa del gobierno, pero los datos de las transacciones siguen fluyendo a Revenue en tiempo real. El calendario por fases y el modelo de reporte de Irlanda están firmemente confirmados por Revenue — incluyendo quién entra en la Fase 1. La especificación técnica detallada (perfil exacto del esquema, detalle de la API) todavía se está finalizando junto con la Autoridad Peppol de Irlanda; las secciones siguientes se marcan como Confirmado o Pendiente de especificación técnica en consecuencia.', 'Aquí no hay un paso de autoevaluación — es Revenue quien le indica si está en la Fase 1, no al revés.', 'Todavía no se ha publicado ningún régimen de sanciones — se espera que llegue junto con las especificaciones técnicas detalladas antes de la Fase 1.' FROM countries WHERE name_en = 'Ireland';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Peppol + Echtzeitmeldung (hybrid)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Irlands genaue technische Spezifikationen, die zu meldenden Datenfelder und das Bußgeldregime werden noch finalisiert — bestätigen Sie aktuelle Anforderungen direkt bei Revenue, bevor Sie eine Integration aufbauen.', 'Irlands Programm zur Umsatzsteuermodernisierung ist schneller als die meisten von der Konsultation zu einem bestätigten Umfang übergegangen — die Steuerpflichtigenkriterien für Phase 1 standen über zwei Jahre vor dem Start fest.', 'Irlands Richtung ist klar, auch wenn die letzten technischen Details noch nicht feststehen — das ist ein klarer Schritt voraus gegenüber der noch offenen Formatfrage im Vereinigten Königreich.', 'Irland liegt zwischen dem rein dezentralen Modell des Vereinigten Königreichs und dem vollständigen Clearing-Modell Frankreichs oder Polens — Rechnungen benötigen keine vorherige behördliche Genehmigung, aber Transaktionsdaten fließen weiterhin in Echtzeit an Revenue. Irlands Zeitplan und Meldemodell sind von Revenue fest bestätigt — einschließlich wer unter Phase 1 fällt. Die detaillierte technische Spezifikation (genaues Schemaprofil, API-Detail) wird noch gemeinsam mit der irischen Peppol-Behörde finalisiert; die folgenden Abschnitte sind entsprechend als Bestätigt oder Technische Spezifikation ausstehend gekennzeichnet.', 'Hier gibt es keinen Selbsteinschätzungsschritt — Revenue teilt Ihnen mit, ob Sie unter Phase 1 fallen, nicht umgekehrt.', 'Es wurde noch kein Bußgeldregime veröffentlicht — dies wird zusammen mit den detaillierten technischen Spezifikationen vor Phase 1 erwartet.' FROM countries WHERE name_en = 'Ireland';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol + déclaration en temps réel (hybride)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les spécifications techniques exactes de l''Irlande, les champs de données à déclarer et le régime de sanctions sont encore en cours de finalisation — confirmez les exigences actuelles directement auprès de Revenue avant de construire une intégration.', 'Le programme de modernisation de la TVA de l''Irlande est passé de la consultation à un périmètre confirmé plus rapidement que la plupart — les critères des contribuables de la Phase 1 ont été arrêtés plus de deux ans avant l''entrée en vigueur.', 'La direction prise par l''Irlande est claire même si les derniers détails techniques ne sont pas figés — une longueur d''avance nette sur la question du format encore ouverte au Royaume-Uni.', 'L''Irlande se situe entre le modèle purement décentralisé du Royaume-Uni et le modèle de contrôle complet de la France ou de la Pologne — les factures n''ont pas besoin d''une approbation gouvernementale préalable, mais les données de transaction continuent d''être transmises à Revenue en temps réel. Le calendrier et le modèle de déclaration de l''Irlande sont fermement confirmés par Revenue — y compris qui relève de la Phase 1. La spécification technique détaillée (profil exact du schéma, détail de l''API) est encore en cours de finalisation avec l''autorité Peppol irlandaise ; les sections ci-dessous sont marquées Confirmé ou Spécification technique en attente en conséquence.', 'Il n''y a pas d''étape d''auto-évaluation ici — c''est Revenue qui vous indique si vous relevez de la Phase 1, pas l''inverse.', 'Aucun régime de sanctions n''a encore été publié — il est attendu en même temps que les spécifications techniques détaillées avant la Phase 1.' FROM countries WHERE name_en = 'Ireland';

