INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Dirección', '[["Estándar", "EN 16931"], ["Implementación típica", "Peppol BIS Billing 3.0 XML"], ["Red", "Peppol"]]', 'Irlanda está planificando explícitamente un modelo basado en Peppol — se trata de una dirección política declarada, no de especulación, aunque la especificación técnica precisa aún se esté elaborando.', NULL, 'Confirmado', 'confirmed' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Richtung', '[["Standard", "EN 16931"], ["Typische Umsetzung", "Peppol BIS Billing 3.0 XML"], ["Netzwerk", "Peppol"]]', 'Irland plant ausdrücklich ein Peppol-basiertes Modell — dies ist erklärte politische Ausrichtung, keine Spekulation, auch wenn die genaue technische Spezifikation noch erarbeitet wird.', NULL, 'Bestätigt', 'confirmed' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Orientation', '[["Norme", "EN 16931"], ["Mise en œuvre typique", "Peppol BIS Billing 3.0 XML"], ["Réseau", "Peppol"]]', 'L''Irlande prévoit explicitement un modèle basé sur Peppol — il s''agit d''une orientation politique déclarée, non d''une spéculation, même si la spécification technique précise est encore en cours d''élaboration.', NULL, 'Confirmé', 'confirmed' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que queda expresamente excluido', '[["PDF", "No son facturas electrónicas válidas a efectos de cumplimiento"], ["Facturas en papel escaneadas", "No son facturas electrónicas válidas a efectos de cumplimiento"]]', 'La comunicación de Revenue de febrero de 2026 fue inequívoca en este punto — no dé por sentado que un flujo de trabajo en PDF "suficientemente estructurado" satisfará la Fase 1.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was ausdrücklich ausgeschlossen ist', '[["PDFs", "Für Konformitätszwecke keine gültigen E-Rechnungen"], ["Gescannte Papierrechnungen", "Für Konformitätszwecke keine gültigen E-Rechnungen"]]', 'Die Mitteilung von Revenue vom Februar 2026 war in diesem Punkt eindeutig — gehen Sie nicht davon aus, dass ein "ausreichend strukturierter" PDF-Workflow Phase 1 erfüllt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qui est explicitement exclu', '[["PDF", "Ne constituent pas des factures électroniques valides à des fins de conformité"], ["Factures papier scannées", "Ne constituent pas des factures électroniques valides à des fins de conformité"]]', 'La communication de Revenue de février 2026 était sans ambiguïté sur ce point — ne présumez pas qu''un flux PDF « suffisamment structuré » satisfera la Phase 1.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Capa de reporte', '[["Qué se reporta", "Un subconjunto especificado de datos de transacciones"], ["Frecuencia", "Tiempo real, por transacción"], ["Comparable a", "PAYE Modernisation, pero para el IVA"]]', 'No se trata de una declaración de IVA periódica — es un flujo de datos en vivo junto con la emisión de cada factura, conceptualmente similar a cómo PAYE Modernisation transformó el reporte de nóminas.', NULL, 'Concepto confirmado', 'confirmed' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Meldeebene', '[["Was gemeldet wird", "Ein festgelegter Teil der Transaktionsdaten"], ["Häufigkeit", "Echtzeit, pro Transaktion"], ["Vergleichbar mit", "PAYE Modernisation, aber für die Umsatzsteuer"]]', 'Dies ist keine periodische Umsatzsteuererklärung — es ist ein Live-Datenfeed parallel zur Ausstellung jeder Rechnung, konzeptionell vergleichbar mit der Art, wie PAYE Modernisation die Lohnabrechnungsmeldung veränderte.', NULL, 'Konzept bestätigt', 'confirmed' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Couche de déclaration', '[["Ce qui est déclaré", "Un sous-ensemble spécifié de données de transaction"], ["Fréquence", "Temps réel, par transaction"], ["Comparable à", "PAYE Modernisation, mais pour la TVA"]]', 'Il ne s''agit pas d''une déclaration de TVA périodique — c''est un flux de données en direct accompagnant l''émission de chaque facture, conceptuellement similaire à la façon dont PAYE Modernisation a transformé la déclaration de paie.', NULL, 'Concept confirmé', 'confirmed' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que aún está pendiente', '[["Campos de datos exactos a reportar", "Aún no publicados"], ["Detalle de API/esquema", "En proceso de finalización con la Autoridad Peppol de Irlanda"]]', 'Revenue se ha comprometido a publicar orientación detallada y especificaciones técnicas antes de cada fase — no fije suposiciones a nivel de campo hasta que eso llegue.', NULL, 'Pendiente de especificación técnica', 'pending' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was noch aussteht', '[["Genaue zu meldende Datenfelder", "Noch nicht veröffentlicht"], ["API-/Schema-Detail", "Wird mit der irischen Peppol-Behörde finalisiert"]]', 'Revenue hat sich verpflichtet, vor jeder Phase detaillierte Hinweise und technische Spezifikationen zu veröffentlichen — legen Sie Annahmen auf Feldebene erst fest, wenn diese vorliegen.', NULL, 'Technische Spezifikation ausstehend', 'pending' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qui reste en attente', '[["Champs de données exacts à déclarer", "Pas encore publiés"], ["Détail API/schéma", "En cours de finalisation avec l''autorité Peppol irlandaise"]]', 'Revenue s''est engagé à publier des directives détaillées et des spécifications techniques avant chaque phase — ne figez pas d''hypothèses au niveau des champs avant que cela ne soit disponible.', NULL, 'Spécification technique en attente', 'pending' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'División de gobernanza', '[["Oficina de Contratación Pública (OGP)", "Autoridad Peppol de Irlanda desde 2018 — infraestructura técnica y de contratación"], ["Revenue Commissioners", "Es titular de la política de Modernización del IVA, el mandato y la capa de reporte"]]', 'Se trata de dos organismos distintos con dos funciones distintas — OGP amplía la red, Revenue define qué debe reportarse a través de ella.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Aufteilung der Zuständigkeiten', '[["Office of Government Procurement (OGP)", "Irische Peppol-Behörde seit 2018 — technische und beschaffungsbezogene Infrastruktur"], ["Revenue Commissioners", "Verantwortlich für die Politik zur Umsatzsteuermodernisierung, die Pflicht und die Meldeebene"]]', 'Dies sind zwei verschiedene Stellen mit zwei verschiedenen Aufgaben — OGP skaliert das Netzwerk, Revenue legt fest, was darüber gemeldet werden muss.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Répartition de la gouvernance', '[["Office of Government Procurement (OGP)", "Autorité Peppol irlandaise depuis 2018 — infrastructure technique et d''approvisionnement"], ["Revenue Commissioners", "Détient la politique de modernisation de la TVA, l''obligation et la couche de déclaration"]]', 'Ce sont deux organismes différents avec deux missions différentes — l''OGP fait évoluer le réseau, Revenue définit ce qui doit être déclaré via celui-ci.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Trabajo de capacidad de red', '[["Marco", "Acuerdo Marco Multiproveedor (organismos públicos)"], ["Enfoque", "Preparar Peppol para una expansión significativa de volumen"]]', 'Revenue está consultando estrechamente con OGP precisamente porque la Fase 1 representa un gran salto en el uso de la red respecto a la base actual, en gran parte voluntaria/del sector público.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Arbeiten zur Netzwerkkapazität', '[["Rahmenvertrag", "Multi-Supplier Framework Agreement (öffentliche Stellen)"], ["Fokus", "Vorbereitung von Peppol auf eine deutliche Volumenausweitung"]]', 'Revenue stimmt sich eng mit OGP ab, gerade weil Phase 1 einen großen Sprung bei der Netzwerknutzung gegenüber der heutigen, weitgehend freiwilligen/öffentlichen Basis darstellt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Travaux sur la capacité du réseau', '[["Cadre", "Accord-cadre multi-fournisseurs (organismes publics)"], ["Priorité", "Préparer Peppol à une expansion significative du volume"]]', 'Revenue se concerte étroitement avec l''OGP précisément parce que la Phase 1 représente un bond important de l''utilisation du réseau par rapport à la base actuelle, largement volontaire/publique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin etapa de compensación (clearance)', '[["Validez de la factura", "No aprobada por el gobierno antes de su efecto legal"], ["Comparación", "A diferencia de los modelos CTC de Francia, Polonia o Italia"]]', 'Esta es la distinción estructural clave respecto a los modelos de compensación continentales — Irlanda combina el intercambio basado en red con una obligación de reporte, en lugar de exigir la aprobación del gobierno para cada factura.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Kein Clearing-Schritt', '[["Gültigkeit der Rechnung", "Keine behördliche Genehmigung vor Rechtswirksamkeit"], ["Vergleich", "Anders als bei den CTC-Modellen Frankreichs, Polens oder Italiens"]]', 'Dies ist der zentrale strukturelle Unterschied zu kontinentalen Clearing-Modellen — Irland verbindet netzwerkbasierten Austausch mit einer Meldepflicht, statt eine behördliche Freigabe für jede Rechnung zu verlangen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Aucune étape de contrôle (clearance)', '[["Validité de la facture", "Non approuvée par le gouvernement avant son effet juridique"], ["Comparaison", "Contrairement aux modèles CTC de la France, de la Pologne ou de l''Italie"]]', 'C''est la distinction structurelle clé par rapport aux modèles de contrôle continentaux — l''Irlande associe un échange basé sur le réseau à une obligation de déclaration, plutôt que d''exiger l''aval du gouvernement pour chaque facture.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'El contexto de la brecha de IVA', '[["Estimación de la Comisión Europea", "~1.700 millones de €, 10,1 % de los ingresos de IVA esperados"], ["Impulsor de la política", "Pasar de declaraciones periódicas a un reporte casi en tiempo real"]]', 'La brecha de IVA de Irlanda está en línea, en términos generales, con la media de la UE — pero es lo suficientemente alta como para que Revenue la haya convertido en la justificación explícita de la capa de reporte de la Fase 1.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Der Kontext der Umsatzsteuerlücke', '[["Schätzung der EU-Kommission", "~1,7 Mrd. €, 10,1 % der erwarteten Umsatzsteuereinnahmen"], ["Politischer Treiber", "Übergang von periodischen Erklärungen zu nahezu Echtzeitmeldung"]]', 'Irlands Umsatzsteuerlücke liegt insgesamt im Rahmen des EU-Durchschnitts — ist aber hoch genug, dass Revenue ihre Schließung zur ausdrücklichen Begründung für die Meldeebene von Phase 1 gemacht hat.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Le contexte de l''écart de TVA', '[["Estimation de la Commission européenne", "~1,7 Md €, soit 10,1 % des recettes de TVA attendues"], ["Moteur politique", "Passage des déclarations périodiques à une déclaration quasi temps réel"]]', 'L''écart de TVA de l''Irlande est globalement conforme à la moyenne de l''UE — mais suffisamment élevé pour que Revenue en ait fait la justification explicite de la couche de déclaration de la Phase 1.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💶 Régimen de sanciones aún no publicado', NULL, NULL, 'Revenue no ha establecido estructuras de aplicación o multas para la Modernización del IVA — trátelo igual que el marco pendiente del Reino Unido: llegará, pero todavía no.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💶 Bußgeldregime noch nicht veröffentlicht', NULL, NULL, 'Revenue hat noch keine Durchsetzungs- oder Bußgeldstrukturen für die Umsatzsteuermodernisierung festgelegt — behandeln Sie dies wie das ausstehende Regime des Vereinigten Königreichs: Es kommt, aber noch nicht.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💶 Régime de sanctions pas encore publié', NULL, NULL, 'Revenue n''a pas encore défini de structures d''application ou d''amendes pour la modernisation de la TVA — traitez cela comme le régime en attente du Royaume-Uni : cela arrive, mais pas encore.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🏛️ El sector público como precedente en funcionamiento', NULL, NULL, 'Los organismos públicos han procesado facturas Peppol EN 16931 desde abril de 2020 — un historial operativo real al que las empresas de la Fase 1 pueden recurrir al planificar su propia integración.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🏛️ Der öffentliche Sektor als funktionierender Präzedenzfall', NULL, NULL, 'Öffentliche Stellen verarbeiten seit April 2020 EN-16931-Peppol-Rechnungen — eine echte operative Erfolgsbilanz, auf die sich Phase-1-Unternehmen bei der Planung ihrer eigenen Integration stützen können.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🏛️ Le secteur public comme précédent opérationnel', NULL, NULL, 'Les organismes publics traitent des factures Peppol EN 16931 depuis avril 2020 — un véritable historique opérationnel sur lequel les entreprises de la Phase 1 peuvent s''appuyer pour planifier leur propre intégration.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🇬🇧 Un contraste útil con el Reino Unido', NULL, NULL, 'Ambos países han optado por Peppol, pero Irlanda lo combina con el reporte en tiempo real a Revenue, mientras que el Reino Unido ha excluido explícitamente el reporte de su mandato de 2029 — algo a tener claro si opera en ambos mercados.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🇬🇧 Ein nützlicher Kontrast zum Vereinigten Königreich', NULL, NULL, 'Beide Länder haben sich für Peppol entschieden, aber Irland verbindet es mit einer Echtzeitmeldung an Revenue, während das Vereinigte Königreich die Meldung ausdrücklich aus seiner Pflicht ab 2029 ausgeschlossen hat — wichtig, wenn Sie in beiden Märkten tätig sind.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🇬🇧 Un contraste utile avec le Royaume-Uni', NULL, NULL, 'Les deux pays ont choisi Peppol, mais l''Irlande l''associe à une déclaration en temps réel à Revenue, tandis que le Royaume-Uni a explicitement exclu la déclaration de son obligation de 2029 — un point à garder à l''esprit si vous opérez sur les deux marchés.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📞 Canal de contacto directo', NULL, NULL, 'Revenue ha abierto un buzón dedicado — vatmodernisation@revenue.ie — específicamente para consultas sobre el despliegue, una señal de que el programa está en desarrollo activo y receptivo, no en una política fija ya publicada y cerrada.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📞 Direkter Kontaktkanal', NULL, NULL, 'Revenue hat ein eigenes Postfach eingerichtet — vatmodernisation@revenue.ie — speziell für Fragen zum Rollout, ein Zeichen dafür, dass sich das Programm in aktiver, reaktionsfähiger Entwicklung befindet und nicht um eine feste, bereits veröffentlichte und abgeschlossene Politik handelt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📞 Canal de contact direct', NULL, NULL, 'Revenue a ouvert une boîte dédiée — vatmodernisation@revenue.ie — spécifiquement pour les questions liées au déploiement, signe que le programme est en développement actif et réactif plutôt qu''une politique fixe déjà publiée et arrêtée.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Ireland' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'No autoevalúe usted mismo el estatus de "gran empresa"', 'Es una definición administrativa vinculada a si sus asuntos fiscales son gestionados por la División de Grandes Empresas de Revenue — no un umbral de facturación o plantilla que usted mismo calcule. Revenue escribirá individualmente a las empresas afectadas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bewerten Sie den Status "Großunternehmen" nicht selbst', 'Es handelt sich um eine administrative Definition, die daran geknüpft ist, ob Ihre Steuerangelegenheiten von der Großunternehmensabteilung von Revenue verwaltet werden — nicht um einen von Ihnen selbst berechneten Umsatz- oder Mitarbeiterschwellenwert. Revenue wird betroffene Unternehmen individuell anschreiben.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'N''auto-évaluez pas votre statut de « grande entreprise »', 'Il s''agit d''une définition administrative liée au fait que vos affaires fiscales sont gérées ou non par la division des grandes entreprises de Revenue — et non d''un seuil de chiffre d''affaires ou d''effectif que vous calculez vous-même. Revenue écrira individuellement aux entreprises concernées.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si está dentro del alcance de la Fase 1, inicie ya la evaluación de preparación de su ERP', 'Hay que construir tanto la emisión como el reporte en tiempo real — esto es más que un cambio de formato, es una nueva canalización de datos en vivo hacia Revenue.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie unter Phase 1 fallen, beginnen Sie jetzt mit der ERP-Bereitschaftsbewertung', 'Sowohl die Ausstellung als auch die Echtzeitmeldung müssen aufgebaut werden — das ist mehr als eine Formatänderung, es ist eine neue Live-Datenpipeline zu Revenue.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous entrez dans le périmètre de la Phase 1, lancez dès maintenant l''évaluation de la préparation de votre ERP', 'L''émission comme la déclaration en temps réel doivent être mises en place — c''est plus qu''un changement de format, c''est un nouveau flux de données en direct vers Revenue.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Toda empresa necesita capacidad de recepción antes de noviembre de 2028', 'Aunque aún no emita facturas, confirme que su software de contabilidad o un Punto de Acceso puede aceptar documentos Peppol entrantes — esta obligación es universal, no se limita a las grandes empresas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Jedes Unternehmen benötigt bis November 2028 Empfangsfähigkeit', 'Auch wenn Sie noch nicht ausstellen, bestätigen Sie, dass Ihre Buchhaltungssoftware oder ein Access Point eingehende Peppol-Dokumente akzeptieren kann — diese Pflicht gilt universell, nicht nur für Großunternehmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Chaque entreprise a besoin d''une capacité de réception d''ici novembre 2028', 'Même si vous n''émettez pas encore de factures, vérifiez que votre logiciel comptable ou un Access Point peut accepter des documents Peppol entrants — cette obligation est universelle, pas limitée aux grandes entreprises.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Esté atento a las especificaciones técnicas de Revenue, fase por fase', 'Supervise el canal dedicado en vatmodernisation@revenue.ie y las orientaciones publicadas por Revenue — no construya sobre supuestos de detalle a nivel de campo antes de que se confirmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Achten Sie auf Revenues phasenweise technische Spezifikationen', 'Verfolgen Sie den eigenen Kanal unter vatmodernisation@revenue.ie sowie die veröffentlichten Hinweise von Revenue — bauen Sie nicht auf angenommenen Details auf Feldebene, bevor diese bestätigt sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez les spécifications techniques de Revenue, phase par phase', 'Suivez le canal dédié à vatmodernisation@revenue.ie et les directives publiées par Revenue — ne construisez pas sur des hypothèses de détail au niveau des champs avant qu''elles ne soient confirmées.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si comercia de forma transfronteriza en la UE, planifique juntas la Fase 1 y la Fase 2', 'Noviembre de 2028 y noviembre de 2029 están separados por solo un año — es más eficiente diseñar su integración teniendo en cuenta ambas fases desde el principio.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie grenzüberschreitend in der EU handeln, planen Sie Phase 1 und Phase 2 gemeinsam', 'November 2028 und November 2029 liegen nur ein Jahr auseinander — es ist effizienter, Ihre Integration von Anfang an mit Blick auf beide Phasen zu gestalten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous pratiquez le commerce transfrontalier au sein de l''UE, planifiez ensemble la Phase 1 et la Phase 2', 'Novembre 2028 et novembre 2029 ne sont séparés que d''un an — il est plus efficace de concevoir votre intégration en tenant compte des deux phases dès le départ.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Ireland' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Revenue — Modernización del IVA / Facturación electrónica' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Ireland' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Revenue — Umsatzsteuermodernisierung / E-Rechnung' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Ireland' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Revenue — Modernisation de la TVA / Facturation électronique' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Ireland' AND dp.sort_order = 0;
